parameters.jsCode:
// Unified telemetry webhook. CRITICAL may propose error-heal (HITL). Notify is Grok Watchdog.
// Telegram optional. Philanthropy/OpenClaw HOLD — not gates.
const body = $json.body || $json;
const correlationId = body.correlationId || body.correlation_id || `tel-${Date.now()}`;
const eventType = body.event_type || body.eventType || 'INFO';
const severity = (body.severity || 'INFO').toUpperCase();
const isCritical = severity === 'CRITICAL' || eventType === 'TEST_FAILURE' || eventType === 'CREATIVE_PIVOT';
const repositoryName = body.repository_name || body.repo || 'n8n-cursor';
const context = body.context || {};

return [{
  json: {
    correlationId,
    eventType,
    severity,
    isCritical,
    repositoryName,
    context,
    hive_state: body.hive_state || {},
    timestamp: body.timestamp || new Date().toISOString(),
    registerPayload: {
      correlationId,
      jobType: 'hive.telemetry.ingested',
      goal: 'Watchdog telemetry sink',
      source: 'hive-telemetry-ingest',
      status: isCritical ? 'need_hitl' : 'done',
      registerTo: 'scorpion',
      summary: `${severity} ${eventType} ${repositoryName}`,
      metadata: {
        lane: 'hive-os',
        eventType,
        severity,
        telegramRequired: 'false'
      }
    },
    healPayload: {
      correlationId,
      statusCode: 500,
      route: context.file_path || 'telemetry',
      error: context.error_message || `${severity} ${eventType}`,
      repo: repositoryName,
      service: 'hive-telemetry'
    }
  }
}];

parameters.jsonBody:
={
  "chat_id": "{{ $env.HIVE_TELEGRAM_CHAT_ID }}",
  "text": {{ JSON.stringify('CRITICAL telemetry ' + $json.correlationId + ' — see Scorpion. Telegram optional.') }}
}
